  `date_of_birth` date DEFAULT NULL,
  `address` varchar(200) DEFAULT NULL,
  `city` int(11) DEFAULT NULL,
  `district` int(11) DEFAULT NULL,
  `kelurahan` int(11) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `job` varchar(100) DEFAULT NULL,
  `agama_id` int(11) DEFAULT NULL,
  `pendidikan_id` int(11) DEFAULT NULL,
  `suku` varchar(255) DEFAULT NULL,
  `bahasa` varchar(255) DEFAULT NULL,
  `is_anggota` int(1) DEFAULT NULL,
  `tni_nrp` varchar(255) DEFAULT NULL,
  `tni_keanggotaan_id` int(11) DEFAULT NULL,
