  `tni_jabatan` varchar(255) DEFAULT NULL,
  `tni_pangkat_singkat` varchar(255) DEFAULT NULL,
  `photo_ori` varchar(300) NOT NULL DEFAULT 'assets/img/placeholder.jpg',
  `photo_thumb` varchar(300) NOT NULL DEFAULT 'assets/img/placeholder.jpg',
  `relatives_id` int(11) DEFAULT NULL,
  `relatives_type` int(1) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `ktp` varchar(20) DEFAULT NULL,
  `type` int(11) DEFAULT NULL COMMENT '1 = General; 2 = TNI; 3 = Kerjasama',
  `treatment_class` varchar(8) DEFAULT NULL COMMENT '1,2,3,vip,vvip',
