  `is_baru` int(11) DEFAULT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `text_asuransi` varchar(255) DEFAULT NULL,
  `text_alamat` varchar(255) DEFAULT NULL,
  `text_kerabat_nrp` varchar(255) DEFAULT NULL,
